from pathlib import Path
p=Path('index.html')
s=p.read_text(errors='surrogateescape')
MARK='MOLMS-V8-SAFE-REINTEGRATION'
if MARK in s:
    print('already patched'); raise SystemExit(0)
required=["sb.auth.signInWithPassword", "const url='https://myjkthjgnmzabmuwprqp.supabase.co'", "<nav class=\"bottom-nav hidden\">", "function _setBottomNavHidden"]
for x in required: assert x in s, f'missing auth guard: {x}'
assert s.count('id="page-findash"')==1
assert s.count('class="sb-clock"')==1
css='''\n<style>\n/* MOLMS-V8-SAFE-REINTEGRATION */\n.sb-v8-context{margin:10px 14px 12px;border:1px solid rgba(255,255,255,.14);border-radius:14px;overflow:hidden;background:rgba(255,255,255,.055)}\n.sb-v8-photo{height:96px;background:url('assets/molms-office-sidebar.webp') center/cover no-repeat;position:relative}.sb-v8-photo:after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(15,36,64,.02),rgba(15,36,64,.78))}\n.sb-v8-copy{padding:11px 12px 12px}.sb-v8-kicker{font-size:9px;letter-spacing:.13em;text-transform:uppercase;color:var(--gold);font-weight:900;margin-bottom:5px}.sb-v8-message{font-family:Georgia,serif;font-size:13px;line-height:1.35;color:#fff}.sb-v8-note{font-size:10px;line-height:1.35;color:rgba(255,255,255,.56);margin-top:5px}\n#fdExecutiveV8{padding:14px 24px 2px}.fdv8-head{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;margin-bottom:10px}.fdv8-title{font-family:Georgia,serif;font-size:18px;font-weight:900;color:var(--navy)}.fdv8-sub{font-size:11px;color:var(--muted);margin-top:2px}.fdv8-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.fdv8-card{background:#fff;border:1px solid var(--border);border-radius:14px;padding:13px;box-shadow:0 3px 12px rgba(15,36,64,.04)}.fdv8-card small{font-size:9px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);font-weight:900}.fdv8-card strong{display:block;font-family:Georgia,serif;font-size:19px;color:var(--navy);margin-top:5px}.fdv8-status{border-left:4px solid var(--gold)}\n@media(max-width:900px){#fdExecutiveV8{padding:12px 12px 2px}.fdv8-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.sb-v8-context{display:none}}\n</style>\n'''
s=s.replace('</head>',css+'</head>',1)
card='''\n    <div class="sb-v8-context" id="sidebarV8Context"><div class="sb-v8-photo" aria-hidden="true"></div><div class="sb-v8-copy"><div class="sb-v8-kicker" id="sidebarV8Kicker">M&amp;O MANAGEMENT</div><div class="sb-v8-message" id="sidebarV8Message">See what needs your attention, then act.</div><div class="sb-v8-note" id="sidebarV8Note">A clear management view — not an accounting screen.</div></div></div>\n'''
s=s.replace('    <div class="sb-clock">',card+'    <div class="sb-clock">',1)
js='''\n<script>\n/* MOLMS-V8-SAFE-REINTEGRATION runtime: additive only; auth/login code untouched. */\n(function(){\n const contexts={dashboard:['FIRM OVERVIEW','Start with what needs attention today.','Urgent matters, deadlines and team activity at a glance.'],cause:['LITIGATION','Stay ahead of the next court step.','Focus on hearings, deadlines and matters requiring action.'],nonlit:['NON-LITIGATION','Keep advisory work moving.','See current work, responsible members and next steps.'],reports:['DAILY REPORTS','Know what was done and what remains.','Review progress without turning MOLMS into an HR system.'],diary:['LEGAL DIARY','Protect every important date.','Hearings, deadlines and commitments in one place.'],documents:['DOCUMENTS','Find the right document quickly.','Keep the matter record organised and accessible.'],chat:['INTERCOM','Keep internal communication inside the work.','Short, relevant and connected to the firm.'],hr:['HR','Manage people without unnecessary complexity.','Employment and leave information only where it helps decisions.'],payroll:['PAYROLL','Complete payroll accurately and move on.','Salary processing with statutory controls, not an accounting suite.'],budget:['OFFICE BUDGET','Approve spending before money moves.','Control requests and commitments with a simple audit trail.'],expenses:['EXPENSE REGISTER','Know what the office has spent.','Record approved expenditure and supporting documents.'],invoice:['INVOICES','From agreed fee to collected cash.','Issue, revise and record payment in one continuous workflow.'],findash:['FINANCIAL DASHBOARD','Know the firm’s financial position in 30 seconds.','Summary first, exceptions second, detail only when needed.'],members:['MEMBERS','Know who is responsible for what.','Keep access and responsibilities current.'],settings:['SETTINGS','Keep MOLMS aligned with the firm.','Change system preferences without disturbing daily work.']};\n function setContext(k){const c=contexts[k]||contexts.dashboard;[['sidebarV8Kicker',0],['sidebarV8Message',1],['sidebarV8Note',2]].forEach(([id,i])=>{const e=document.getElementById(id);if(e)e.textContent=c[i]})}\n document.addEventListener('click',e=>{const n=e.target.closest('[data-nav]');if(n)setContext(n.dataset.nav)});\n const money=v=>'TZS '+Number(v||0).toLocaleString();\n function build(){const root=document.getElementById('page-findash'),k=document.getElementById('fdKpiRow');if(!root||!k)return;let h=document.getElementById('fdExecutiveV8');if(!h){h=document.createElement('div');h.id='fdExecutiveV8';k.parentNode.insertBefore(h,k)}let m={},st={};try{if(typeof fdMetrics==='function')m=fdMetrics()||{}}catch(e){}try{if(typeof fdHealth==='function')st=fdHealth()||{}}catch(e){}h.innerHTML='<div class="fdv8-head"><div><div class="fdv8-title">Executive financial view</div><div class="fdv8-sub">The numbers that require a management decision now.</div></div><div class="pill gold">'+(st.level||'Current position')+'</div></div><div class="fdv8-grid"><div class="fdv8-card"><small>Revenue</small><strong>'+money(m.revenue)+'</strong></div><div class="fdv8-card"><small>Collected</small><strong>'+money(m.collected)+'</strong></div><div class="fdv8-card"><small>Available cash</small><strong>'+money(m.cash)+'</strong></div><div class="fdv8-card fdv8-status"><small>Outstanding</small><strong>'+money(m.outstanding)+'</strong></div></div>'}\n const r=window.fdRender;if(typeof r==='function')window.fdRender=async function(){const x=await r.apply(this,arguments);build();return x};const f=window.fdRefresh;if(typeof f==='function')window.fdRefresh=async function(){const x=await f.apply(this,arguments);build();return x};window.addEventListener('load',()=>{setContext(typeof page==='string'?page:'dashboard');[500,1200,2200].forEach(t=>setTimeout(build,t))});\n})();\n</script>\n'''
s=s.replace('</body>',js+'</body>',1)
p.write_text(s,errors='surrogateescape')
print('patched',len(s))
